userscript.function:

const header = gridObj.getColumnId(cInd);

if(['SUBJECT', 'SMR_NUMBER'].includes(header)) {
    gridObj.editStop();

    let targetPage = '';
    const rowData = gridObj._getRowData(rId);
    switch(rowData.APPLY_TYPE) {
        case 'U' : 
            targetPage = '/Seal/Document/Use/SealDocumentUseWrite.sux';
            break;
        case 'C' :
            targetPage = '/Seal/Document/Corp/SealDocumentCorpWrite.sux'; 
            break;
        case 'D' :
            targetPage = '/Seal/Document/Cert/SealDocumentCertWrite.sux'; 
            break;
        default:
            break;
    }

    if(targetPage != '') {
        PopupOpenPost(targetPage, {
            SMR_NUMBER : rowData.SMR_NUMBER
        }, undefined, 1280, 720, Sepoa.cache.text.get('SLM_200.LAYOUT_A_HEADER'));
    }
}


            var selectedRow = gridObj.getGridChangedRows("SELECTED");
            if (selectedRow.length < 1) {
                Alert(Sepoa.cache.text.get('MESSAGE.9999'));
                return;
            } else if(selectedRow.length > 1){
                Alert(Sepoa.cache.text.get('POA_CONTRACT.MESSAGE_0006'));
                return;
            } else {
                const rowData = gridObj._getSelectedData('SELECTED')[selectedRow[0]];
                let data = {
                    document: {
                        SMR_NUMBER : rowData.SMR_NUMBER,
                        APPLY_TYPE : rowData.APPLY_TYPE,
                        SUBJECT : rowData.SUBJECT,
                        REQ_SEAL_USE_TYPE : rowData.REQ_SEAL_USE_TYPE,
                        ADD_DATE_TIME : rowData.ADD_DATE_TIME,
                        ADD_USER_NAME : rowData.ADD_USER_NAME,
                        ADD_USER_DEPT : rowData.ADD_USER_DEPT,
                    },
                    view: 'FORM'
                }

                let signerList = []
                doServiceAjax("sepoa.svc.cbo.ct.ContractObjectListService", 'CONNECTION', "doSelectContractObjectExtraData", {SMR_NUMBER : rowData.SMR_NUMBER}, function(so) {
                	if (so.status == 1) {
                		let result = so.result[0];
                		if(result != "__NO_EXTRA_DATA__") {
	                		signerList = JSON.parse(so.result[0]);
                		} 
	                } else {
	                    Alert(so.message);
	                }
	            }, false);

	            data.data = {
	            	CONT_SUBJECT: rowData.SUBJECT,
	            	SIGNER : signerList
	            }

                callFunction(['p', 'p'], 'changeView', [data]);
            }

            if(true) {
                console.log('test');
            } else if (selectedRow.length > 1) {
                if (!sUtils.workflow.check('CT1661237936307')) { //갑지 계약자 그리드 사용모듈
                    Alert(Sepoa.cache.text.get('MESSAGE.1006'));
                    return;
                } else {
                    var first_wkey = ''; //동일한 문서를 가지고 계약서 작성하는지 판단하는 키
                    var doc_no_ar = [];
                    var sux_wkey1_ar = [];
                    var sux_wkey2_ar = [];
                    var sux_wkey3_ar = [];
                    var sux_wkey4_ar = [];
                    var sux_wkey5_ar = [];
                    var sux_wkey6_ar = [];
                    var sux_wkey7_ar = [];
                    var sux_wkey8_ar = [];
                    var sux_wkey9_ar = [];
                    var sux_wkey10_ar = [];
                    for (var i = 0; i < selectedRow.length; i++) {
                        var grid = gridObj._getSelectedData('SELECTED')[selectedRow[i]];
                        if (first_wkey == '') {
                            first_wkey = grid.SUX_WKEY2 + grid.SUX_WKEY3; //입찰 에서의 문서키(RFQ_NUMBER+RFQ_COUNT);
                        } else {
                            if (first_wkey != grid.SUX_WKEY2 + grid.SUX_WKEY3) {
                                Alert(Sepoa.cache.text.get('CT_201.MESSAGE001')); //동일한 문서로만 계약서 생성이 가능합니다
                                return false;
                            }
                        }
                        doc_no_ar[i] = grid.DOC_NO;
                        sux_wkey1_ar[i] = grid.SUX_WKEY1;
                        sux_wkey2_ar[i] = grid.SUX_WKEY2;
                        sux_wkey3_ar[i] = grid.SUX_WKEY3;
                        sux_wkey4_ar[i] = grid.SUX_WKEY4;
                        sux_wkey5_ar[i] = grid.SUX_WKEY5;
                        sux_wkey6_ar[i] = grid.SUX_WKEY6;
                        sux_wkey7_ar[i] = grid.SUX_WKEY7;
                        sux_wkey8_ar[i] = grid.SUX_WKEY8;
                        sux_wkey9_ar[i] = grid.SUX_WKEY9;
                        sux_wkey10_ar[i] = grid.SUX_WKEY10;
                    }
                    var data = {
                        document: {
                            DOC_NO: doc_no_ar.join(','),
                            DOC_TYPE: gridObj._getSelectedData('SELECTED')[selectedRow[0]].DOC_TYPE,
                            SUX_WKEY1: sux_wkey1_ar.join(','),
                            SUX_WKEY2: sux_wkey2_ar.join(','),
                            SUX_WKEY3: sux_wkey3_ar.join(','),
                            SUX_WKEY4: sux_wkey4_ar.join(','),
                            SUX_WKEY5: sux_wkey5_ar.join(','),
                            SUX_WKEY6: sux_wkey6_ar.join(','),
                            SUX_WKEY7: sux_wkey7_ar.join(','),
                            SUX_WKEY8: sux_wkey8_ar.join(','),
                            SUX_WKEY9: sux_wkey9_ar.join(','),
                            SUX_WKEY10: sux_wkey10_ar.join(',')
                        },
                        form: {
                            DOC_TYPE: "PO"
                        },
                        view: 'FORM'
                    }
                    console.log(data)
                    callFunction(['p', 'p'], 'changeView', [data]);
                }
            } else {
                var blackacre_flag = gridObj.gridGetCellValueId(selectedRow[0], 'BLACKACRE_FLAG'); //갑지사용여부
                if ('Y' == blackacre_flag) {
                    var gridData = gridObj._getRowData(selectedRow);
                    var data = {
                        document: {
                            DOC_NO: gridData.DOC_NO,
                            DOC_TYPE: gridData.DOC_TYPE,
                            SUX_WKEY1: gridData.SUX_WKEY1,
                            SUX_WKEY2: gridData.SUX_WKEY2,
                            SUX_WKEY3: gridData.SUX_WKEY3,
                            SUX_WKEY4: gridData.SUX_WKEY4,
                            SUX_WKEY5: gridData.SUX_WKEY5,
                            SUX_WKEY6: gridData.SUX_WKEY6,
                            SUX_WKEY7: gridData.SUX_WKEY7,
                            SUX_WKEY8: gridData.SUX_WKEY8,
                            SUX_WKEY9: gridData.SUX_WKEY9,
                            SUX_WKEY10: gridData.SUX_WKEY10
                        },
                        form: {
                            DOC_TYPE: "PO"
                        },
                        view: 'FORM'
                    }
                    callFunction(['p', 'p'], 'changeView', [data]);
                } else if ('N' == blackacre_flag) {
                    doSave();
                }
            }


var title = '';
var params = {};

gridObj.editStop();
if (gridObj.getRowsNum() < 1) {
    Alert(Sepoa.cache.text.get('MESSAGE.0004'));
    return;
}
var selectedRows = gridObj.getGridChangedRows("SELECTED");
if (selectedRows.length < 1) {
    Alert(Sepoa.cache.text.get('MESSAGE.1004')); //선택된 데이터가 없습니다.
    return;
}
var numbers = new Array();
for (var _idx in selectedRows) {
    var rIdx = selectedRows[_idx];
    var docNumber = gridObj.cells(rIdx, gridObj.getColIndexById('DOC_NO')).getValue();
    numbers.push(docNumber);
}

var seller_code;
var doc_type;
var selectedRow = gridObj.getGridChangedRows("SELECTED");
for (var i = selectedRow.length - 1; i >= 0; i--) {
    if (i == (selectedRow.length - 1)) {
        seller_code = gridObj.gridGetCellValueId(selectedRow[i], 'SELLER_CODE');
        doc_type = gridObj.gridGetCellValueId(selectedRow[i], 'DOC_TYPE');
        continue;
    }
    if (seller_code != gridObj.gridGetCellValueId(selectedRow[i], 'SELLER_CODE')) {
        Alert('업체가 일치하지 않습니다.');
        return;
    }
    if (doc_type != gridObj.gridGetCellValueId(selectedRow[i], 'DOC_TYPE')) {
        Alert('문서타입이 일치하지 않습니다.');
        return;
    }
}

dataOutput.setValue('NUMBERS', numbers.join(','));

params.mode = "ireport"
params.PROCESS_ID = "sepoa.svc.ct.CT_PDF_001";
if (doc_type == "C") { //정단가
    params.METHOD = "doQueryCTPA";
} else { //부품계발
    params.METHOD = "doQueryCTPD";
}
params.HOUSE_CODE = gridObj.cells(gridObj.getRowId(0), gridObj.getColIndexById('HOUSE_CODE')).getValue();
params.COMPANY_CODE = gridObj.cells(gridObj.getRowId(0), gridObj.getColIndexById('COMPANY_CODE')).getValue();
params.SELLER_CODE = gridObj.cells(gridObj.getRowId(0), gridObj.getColIndexById('SELLER_CODE')).getValue();
params.NUMBERS = numbers.join(',');

SUX.root.PopupOpenPost('/UxDefault/Common/PDFViewer.sux', params, undefined, (SUX.root.innerWidth * 0.7), (SUX.root.innerHeight * 0.9), '', title);


gridObj.editStop();
if (gridObj.getRowsNum() < 1) {
    Alert(Sepoa.cache.text.get('MESSAGE.0004'));
    return;
}
var selectedRows = gridObj.getGridChangedRows("SELECTED");
if (selectedRows.length < 1) {
    Alert(Sepoa.cache.text.get('MESSAGE.1004')); //선택된 데이터가 없습니다.
    return;
}
var numbers = new Array();
for (var _idx in selectedRows) {
    var rIdx = selectedRows[_idx];
    var docNumber = gridObj.cells(rIdx, gridObj.getColIndexById('DOC_NO')).getValue();
    numbers.push(docNumber);
}

var seller_code;
var doc_type;
var selectedRow = gridObj.getGridChangedRows("SELECTED");
for (var i = selectedRow.length - 1; i >= 0; i--) {
    if (i == (selectedRow.length - 1)) {
        seller_code = gridObj.gridGetCellValueId(selectedRow[i], 'SELLER_CODE');
        doc_type = gridObj.gridGetCellValueId(selectedRow[i], 'DOC_TYPE');
        continue;
    }
    if (seller_code != gridObj.gridGetCellValueId(selectedRow[i], 'SELLER_CODE')) {
        Alert('업체가 일치하지 않습니다.');
        return;
    }
    if (doc_type != gridObj.gridGetCellValueId(selectedRow[i], 'DOC_TYPE')) {
        Alert('문서타입이 일치하지 않습니다.');
        return;
    }
}
var data = {
    NUMBERS: numbers.join(','),
    DOC_TYPE: doc_type,
    SELLER_CODE: seller_code
};

doServiceAjax("sepoa.svc.ct.CT_206", 'TRANSACTION', "doSavePDF", data, function(so) {
    if (so.status == 1) {
        callContractEditor(so.result[0], so.result[1]);
        callFunction(['p', 'p'], 'changeView', [{
            view: 'LIST'
        }]);
    } else {
        Alert(so.message);
    }
});


sUtils.popup.modal({
    url: window.CONTEXT_NAME + '/Contract/Module/ContractModuleLayout.sux',
    params: {
        CONT_NO: contNo,
        CONT_GL_SEQ: contGlSeq,
        CONT_MODULE: 'EDITOR'
    },
    title: sUtils.cache.text.get('POA_CONTRACT.TITLE_EDITOR')
});


var mode = obj.mode;
var status = obj.status;
var message = obj.message;
var method = obj.method;

if (status == 'true') {
    doQuery();
} else {
    Alert(message);
}
